package analysis

import (
	"math"
	"sort"
)

// Eddington describes the Eddington number of a set of days.
type Eddington struct {
	// E is the largest number such that on E days at least E km were covered.
	E int
	// Next is E+1, the next milestone.
	Next int
	// DaysAtNext counts the days with at least Next km so far.
	DaysAtNext int
	// Missing is the number of further days with at least Next km needed.
	Missing int
}

// ComputeEddington derives the Eddington number from the distance per day in
// km. Multiple activities on one day must be summed beforehand (the classic
// definition counts days, not rides).
func ComputeEddington(dailyKm []float64) Eddington {
	d := append([]float64(nil), dailyKm...)
	sort.Sort(sort.Reverse(sort.Float64Slice(d)))
	e := 0
	for i, km := range d {
		// Day i+1 in descending order must have covered at least i+1 km.
		if math.Floor(km) >= float64(i+1) {
			e = i + 1
		} else {
			break
		}
	}
	res := Eddington{E: e, Next: e + 1}
	for _, km := range d {
		if math.Floor(km) >= float64(res.Next) {
			res.DaysAtNext++
		}
	}
	res.Missing = res.Next - res.DaysAtNext
	return res
}
